    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 10 * 8500 + 20 * 980;
