import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a valid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Icon set (24 icons)');
});

test('createInvoice rejects unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects date without time component', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10-07-2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects invalid date values', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-32',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-array lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -1 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NOPE', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice copies product data without mutation', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  };
  const r1 = createInvoice(input);
  r1.value.lines[0].unitPrice = 9999;
  const r2 = createInvoice(input);
  assert.equal(r2.value.lines[0].unitPrice, 8500);
});

test('createInvoice rejects invalid quantity type', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 'five' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1299 }), 1299);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals sums multiple line items', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 980 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500 + 1960 + 120000);
  assert.equal(totals.total, 42500 + 1960 + 120000);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 3 * 8500 + 2 * 980;
  const expectedDiscount = Math.round((3 * 8500 * 5) / 100) + Math.round((2 * 980 * 5) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = addLine(invoice, { sku: 'ICON-SET', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'ICON-SET');
  assert.equal(r.value.lines[1].qty, 2);
  assert.equal(r.value.lines[1].name, 'Icon set (24 icons)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = addLine(invoice, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects invalid quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const finalized = { ...invoice, status: 'finalized' };
  assert.deepEqual(addLine(finalized, { sku: 'ICON-SET', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  addLine(invoice, { sku: 'ICON-SET', qty: 2 });
  assert.equal(invoice.lines.length, 1);
});

test('removeLine removes a line from an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;
  const r = removeLine(invoice, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'ICON-SET');
});

test('removeLine reports line not found', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  assert.deepEqual(removeLine(invoice, 'NOPE'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;
  const finalized = { ...invoice, status: 'finalized' };
  assert.deepEqual(removeLine(finalized, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;
  removeLine(invoice, 'DES-HOUR');
  assert.equal(invoice.lines.length, 2);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
  assert.equal(r.value.status, 'issued');
  assert.equal(r.value.customerId, 'C-001');
});

test('issueInvoice uses existing numbers to determine next number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice refuses to issue non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued = { ...invoice, status: 'issued' };
  assert.deepEqual(issueInvoice(issued, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  issueInvoice(invoice, []);
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves all invoice data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;
  const r = issueInvoice(invoice, ['INV-2026-0001']);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
});

test('createInvoice accepts discountPercent on a line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice applies tier discount by default', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice rejects negative discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects discountPercent above 100', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects non-numeric discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice rejects null discountPercent', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: null }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice accepts 0 and 100 as valid boundaries', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.lines[0].discountPercent, 0);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 100 }],
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].discountPercent, 100);
});

test('lineDiscount calculates discount from discountPercent', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 50 }), 5000);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 8500, discountPercent: 12.5 }), 1062);
});

test('lineDiscount defaults discountPercent to 0 if not provided', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount clamps discount to 0 minimum', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: -1000, discountPercent: 10 }), 0);
});

test('lineVAT calculates VAT on line after discount', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }), 2100);
  assert.equal(lineVAT({ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 9 }), 900);
  assert.equal(lineVAT({ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }), 0);
});

test('lineVAT calculates VAT after applying discount', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }), 1890);
  assert.equal(lineVAT({ qty: 100, unitPrice: 100, discountPercent: 50, vatRate: 21 }), 950);
});

test('lineVAT with different VAT rates', () => {
  const line = { qty: 1, unitPrice: 10000, discountPercent: 0 };
  assert.equal(lineVAT({ ...line, vatRate: 0 }), 0);
  assert.equal(lineVAT({ ...line, vatRate: 9 }), 900);
  assert.equal(lineVAT({ ...line, vatRate: 21 }), 2100);
});

test('lineVAT clamps VAT to 0 minimum', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: -1000, discountPercent: 0, vatRate: 21 }), 0);
});

